// g_writeJsonFile
//
// Writes a JavaScript object to a formatted JSON file.
//
// Returns:
//   true  - Success
//   false - Failure
// -----------------------------------------------------------------------------

function g_writeJsonFile(FQN, object) {
    try {

        fs.writeFileSync(
            FQN,
            JSON.stringify(object, null, 2) + "\n",
            "utf8"
        );

        return true;

    } catch (err) {

        node.error(
            `g_writeJsonFile(): Unable to write '${FQN}': ${err.message}`
        );

        return false;
    }
}

