// -----------------------------------------------------------------------------
// g_findAlert
//
//Finds an alert by alertId.
//
// Parameters:
//   alerts  - Object containing alerts.
//   alertId - Alert identifier.
//
// Returns:
//   Alert object if found.
//   null if not found.
// -----------------------------------------------------------------------------

function g_findAlert(alerts, alertId) {

    if (!alerts)
        return null;

    if (!alerts[alertId])
        return null;

    return alerts[alertId];

}

global.set("g_findAlert", g_findAlert);

// -----------------------------------------------------------------------------
// g_notificationSent
//
// Updates an alert after a notification has been sent.
//
// Parameters:
//   alert - Alert object.
//
// Returns:
//   Alert object.
// -----------------------------------------------------------------------------

function g_notificationSent(alert) {

    if (!alert)
        return null;

    alert.lastNotification = Date.now();
    alert.notificationCount++;

    return alert;

}

global.set("g_notificationSent", g_notificationSent);

// -----------------------------------------------------------------------------
// g_addAlert
//
// Creates a new alert and adds it to the specified alert table.
//
// Parameters:
//   alerts  - Object containing alerts.
//   alertId - Alert identifier.
//
// Returns:
//   Newly created alert object.
// -----------------------------------------------------------------------------

function g_addAlert(alerts, alertId) {

    const g_newObject = global.get("g_newObject");

    const alert = g_newObject("ACTIVE_NOTIF");

    const now = Date.now();

    alert.notificationId = alertId;
    alert.startedAt = now;
    alert.lastReceivedAt = now;

    alerts[alertId] = alert;

    return alert;

}

global.set("g_addAlert", g_addAlert);

// -----------------------------------------------------------------------------
// g_removeAlert
//
// Removes an alert from the specified alert table.
//
// Parameters:
//   alerts  - Object containing alerts.
//   alertId - Alert identifier.
//
// Returns:
//   true  - Alert was removed.
//   false - Alert was not found.
// -----------------------------------------------------------------------------

function g_removeAlert(alerts, alertId) {

    if (!alerts)
        return false;

    if (!alerts[alertId])
        return false;

    delete alerts[alertId];

    return true;

}

global.set("g_removeAlert", g_removeAlert);

