function assignEventUuid(logEvent) {
    logEvent.eventUuid = crypto.randomUUID();
}

/*-----  ASSIGN THE SEQUENCE NUMBER AND TAKE CARE OF ANY NEXT RESERVE ACTIONS NEEDED  -----*/

function assignSequence(logEvent) {

    const opsLogging = global.get("opsLogging");
    const g_saveOpsLogging = global.get("g_saveOpsLogging");

    logEvent.sequence = opsLogging.nextSequence++;

    if (opsLogging.nextSequence >=
        opsLogging.nextReserve - SEQUENCE_RESERVE_MARGIN) {

        opsLogging.nextSequence = opsLogging.nextReserve;
        opsLogging.nextReserve += SEQUENCE_BLOCK_SIZE;

        g_saveOpsLogging();
    }
}

/*-----  ASSIGN THE RECEIVED TIME  -----*/

function assignReceivedTime(logEvent) {
    logEvent.receivedTime = new Date().toISOString();
}

// -----------------------------------------------------------------------------
// Complete LogEvent
//
// Apply Logging Service policy to a canonical LogEvent.
// -----------------------------------------------------------------------------

/*-----  MAIN  -----*/

assignReceivedTime(logEvent);
assignSequence(logEvent);
assignEventUuid(logEvent);

return msg;

