/*
 * Process Data
 *
 * Input:
 *
 *   sourced/from/file
 *       flow.events already contains the events read from the log file.
 *
 *   sourced/from/tail
 *       msg.payload contains JSON string(s) from tail-file.
 *
 *
 * Output 1 → System dropdown
 * Output 2 → Fields dropdown
 * Output 3 → Update Event State
 *
 *
 * Event data is owned by flow.events.
 *
 * Common event form:
 *
 * {
 *     event: { ...original event... },
 *     show: true,
 *     pending: true
 * }
 */


// -----------------------------------------------------------------------------
// Process one event
// -----------------------------------------------------------------------------

function processEvent(event) {

    return {
        event: event,
        show: true,
        pending: true
    };
}


// -----------------------------------------------------------------------------
// Process events from the initial file read
// -----------------------------------------------------------------------------

function fromReadFile() {

    const events = flow.get("events") || [];

    const processedEvents = events.map(event =>
        processEvent(event)
    );

    flow.set("events", processedEvents);
}


// -----------------------------------------------------------------------------
// Process events from tail-file
// -----------------------------------------------------------------------------

function fromTailFile() {

    let incomingEvents = msg.payload;

    // Normally tail-file supplies one JSON string.
    // Accept an array as well so this remains safe if that ever changes.
    if (!Array.isArray(incomingEvents)) {
        incomingEvents = [incomingEvents];
    }

    const newEvents = [];

    for (const incomingEvent of incomingEvents) {

        let event = incomingEvent;


        // ---------------------------------------------------------------------
        // Convert JSON string to event object
        // ---------------------------------------------------------------------

        if (typeof event === "string") {

            try {
                event = JSON.parse(event);
            }
            catch (err) {

                node.error(
                    `Unable to parse tailed event: ${err.message}`,
                    msg
                );

                continue;
            }
        }


        // ---------------------------------------------------------------------
        // Validate event
        // ---------------------------------------------------------------------

        if (
            !event ||
            typeof event !== "object" ||
            Array.isArray(event)
        ) {

            node.error(
                "Invalid event received from tail-file.",
                msg
            );

            continue;
        }


        // ---------------------------------------------------------------------
        // Process new event
        // ---------------------------------------------------------------------

        newEvents.push(
            processEvent(event)
        );
    }


    // -------------------------------------------------------------------------
    // Nothing usable arrived
    // -------------------------------------------------------------------------

    if (newEvents.length === 0) {
        return;
    }


    // -------------------------------------------------------------------------
    // Append new events to existing collection
    // -------------------------------------------------------------------------

    const events = flow.get("events") || [];

    events.push(...newEvents);

    flow.set("events", events);
}


// -----------------------------------------------------------------------------
// Select the source
// -----------------------------------------------------------------------------

switch (msg.topic) {

    case "sourced/from/file":
        fromReadFile();
        break;


    case "sourced/from/tail":
        fromTailFile();
        break;


    default:

        node.error(
            `Unknown message source: ${msg.topic}`,
            msg
        );

        return null;
}


// -----------------------------------------------------------------------------
// Everything below this point operates on the same flow.events structure,
// regardless of where the events came from.
// -----------------------------------------------------------------------------

const processedEvents = flow.get("events") || [];


// -----------------------------------------------------------------------------
// Build System dropdown
// -----------------------------------------------------------------------------

const systems = [
