// -----------------------------------------------------------------------------
// Receive HB
//
// Records receipt of a heartbeat from an accepted device.
//
// Unregistered or unaccepted devices are silently ignored.
// Registration Service owns notification of unknown devices.
//
// Online/offline state is determined exclusively by Timer_tick.
// -----------------------------------------------------------------------------

const sourceId = msg.payload?.sourceId;

if (!sourceId) {
    return null;
}

const devices = global.get("devices") || {};
const device = devices[sourceId];

// -----------------------------------------------------------------------------
// Only accepted devices participate in Heartbeat Service.
// -----------------------------------------------------------------------------

if (!device || !device.registration?.accepted) {
    return null;
}

// -----------------------------------------------------------------------------
// Heartbeat monitoring must be enabled.
// -----------------------------------------------------------------------------

if (!device.heartbeatMonitoring?.enabled) {
    return null;
}

if (!device.heartbeat) {
    return null;
}

