//
// Ordinary timer ticks produce no message.
// -----------------------------------------------------------------------------

if (events.length === 0) {
    return null;
}


// -----------------------------------------------------------------------------
// Return one message for each state transition.
// -----------------------------------------------------------------------------

return events.map(event => ({
